head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedRowColor]<br/>현재 포커스된 Row 의 배경색으로 적용될 색상을 설정합니다. focusMode='row','both' 인 경우에 동작합니다.",
    "validation" : [
        "RowNum Column 에 selectedRowColor 를 적용하려면 rowNumRowMouseOverColor=true 이거나 rowNumBackgroundColor 가 미설정이어야 하며, RowStatus Column 의 배경색에는 항상 selectedRowColor 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - focusMode='row' 는 selectedRowColor 가 동작하는 모드이므로 하드코딩
    //  - rowNumVisible / rowStatusVisible 는 RowNum / RowStatus Column 가시화를 위해 true 하드코딩
    //  - rowNumRowMouseOverColor (true/false), rowNumBackgroundColor (색상) 는 con_ 으로 노출하여 RowNum 적용 조건 검증
    let properties = {
        dataList               : "data:dlt_bind",
        focusMode              : "row",
        rowNumVisible          : "true",
        rowStatusVisible       : "true",
        rowStatusHeaderValue   : "St.",
        selectedRowColor       : con_selectedRowColor.getValue(),
        rowNumRowMouseOverColor: con_rowNumRowMouseOverColor.getText(),
        rowNumBackgroundColor  : con_rowNumBackgroundColor.getValue()
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    //  - oncellclick : 사용자가 Cell 을 클릭해 포커스가 이동하면(focusMode=row → Row 전체 포커스)
    //    포커스된 Row 의 RowNum / RowStatus Cell 배경색을 자동 출력
    let eList = $c.gcm.createEList(["oncellclick"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblRow = (properties.selectedRowColor === '') ? '미설정' : properties.selectedRowColor;
    let lblNumOver = (properties.rowNumRowMouseOverColor === '') ? '미설정' : properties.rowNumRowMouseOverColor;
    let lblNumBg = (properties.rowNumBackgroundColor === '') ? '미설정' : properties.rowNumBackgroundColor;
    $c.gcm.createLabel('label="focusMode=row / rowNumVisible=true / rowStatusVisible=true (고정) / selectedRowColor=' + lblRow + ' / rowNumRowMouseOverColor=' + lblNumOver + ' / rowNumBackgroundColor=' + lblNumBg + ' 로 GridView 생성. 셀을 클릭하면 포커스된 Row 의 RowNum / RowStatus Cell 배경색 출력"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncellclick : 사용자가 Cell 을 마우스 왼쪽 버튼으로 클릭하면 발생 (focusMode=row → 클릭된 Row 전체 포커스)
//  - 포커스된 Row 의 RowNum / RowStatus Cell 의 실제 적용 배경색을 출력 (selectedRowColor 적용 확인)
//  - RowNum  : rowNumRowMouseOverColor=true 또는 rowNumBackgroundColor 미설정 시 selectedRowColor 적용, 그 외 rowNumBackgroundColor 유지
//  - RowStatus: 항상 selectedRowColor 적용
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    // 포커스 배경색 적용은 클릭 처리 직후 반영되므로 다음 tick 에서 read
    setTimeout(function () {
        // RowNum Cell 배경색
        let numTd = document.querySelector("td[id*='target1_headerRowNumber_bodyRow_" + rowIndex + "']");
        let numColor = numTd ? window.getComputedStyle(numTd).backgroundColor : "(cell 없음)";

        // RowStatus Cell 배경색
        let statusTd = document.querySelector("td[id*='target1_headerRowStatus_bodyRow_" + rowIndex + "']");
        let statusColor = statusTd ? window.getComputedStyle(statusTd).backgroundColor : "(cell 없음)";

        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick (Row " + rowIndex + " 포커스)=====");
        wf_body_bottom.getObj("scwin").setReturnValue("[RowNum Cell 배경색] " + numColor);
        wf_body_bottom.getObj("scwin").setReturnValue("[RowStatus Cell 배경색] " + statusColor);
    }, 0);
}
